                )
        for row in queued:
            if row["用户"] not in self._auth:
                raise ResourceError(
                    f"checkpoint references unregistered user: {row['用户']!r}"
                )
        live_sessions = [
            row for row in sessions if row["状态"] != _STATE_OFFLINE
        ]
