    if (events[-1][10] if events else "0" * 64) != tail_hash:
        raise ValueError("计费.尾哈希 does not match the last event hash")

    # 活动行：键序、类型、取值、按会话升序互异；与链重放在账态核对。
    active_rows = []
    active_sids = set()
